#!/bin/zsh
# Builds the checklist widget into ~/.local/bin and restarts its LaunchAgent if loaded.
# Rerun this if you move this folder, so the widget can find worklist-location.txt.
set -e
cd "$(dirname "$0")"
cat > BuildPaths.swift <<SWIFT
// Generated by build.sh; do not edit.
let locationFilePath = "$PWD/worklist-location.txt"
SWIFT
# Build to a temp file and move it into place, so the running copy isn't overwritten mid-use.
swiftc -O -parse-as-library ChecklistWidget.swift BuildPaths.swift -o "$HOME/.local/bin/checklist-widget.new"
mv -f "$HOME/.local/bin/checklist-widget.new" "$HOME/.local/bin/checklist-widget"
echo "built $HOME/.local/bin/checklist-widget"
launchctl kickstart -k "gui/$UID/com.haydenfletcher.checklistwidget" 2>/dev/null && echo "restarted widget" || true
